style.css:
@-moz-document domain("youtube.com") {
/* ? Fondo principal (tu imagen) */
    body {
        background-image: url("https://i.pinimg.com/1200x/fe/50/5c/fe505c47473807a7bafc48ccfece4829.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    /* ? Fondos de YouTube transparentes */
    html,
    ytd-app,
    ytd-page-manager,
    #content,
    #container,
    #page-manager {
        background: transparent !important;
    }

    /* ? Tarjetas */
    ytd-rich-item-renderer,
    ytd-video-renderer,
    ytd-grid-video-renderer {
        background: rgba(0, 0, 0, 0.2) !important;
        border-radius: 12px !important;
        padding: 6px !important;
    }

    /* ? Sidebar */
    ytd-guide-renderer,
    ytd-mini-guide-renderer {
        background: rgba(0, 0, 0, 0.15) !important;
    }

    /* ? Barra superior */
    #masthead {
        background: rgba(0, 0, 0, 0.25) !important;
        backdrop-filter: blur(6px) !important;
    }

    /* ? Barra de búsqueda estilo glassmorphism */
    #search {
        background: rgba(255, 255, 255, 0.1) !important; /* ligero transparente */
        backdrop-filter: blur(15px) !important; /* difumina lo que hay detrás */
        border-radius: 20px !important;
        color: white !important;
    }

    /* ? Todo el texto en blanco */
    * {
        color: white !important;
    }

    /* ✨ Overlay ligero para letras */
    body::before {
        content: "";
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.08);
        z-index: -1;
    }
}
